package com.shahabsystem.livewebwallpaper;
import android.app.*;import android.app.WallpaperManager;import android.content.*;import android.graphics.Color;import android.os.*;import android.view.*;import android.widget.*;import android.net.Uri;
public class MainActivity extends Activity { LinearLayout l; EditText url; SeekBar sp,cp,dim,zoom; Spinner mode; int bg=0xFF050607,ac=0xFFFF6A00; TextView tv(String s){TextView t=new TextView(this);t.setText(s);t.setTextSize(15);t.setPadding(0,8,0,5);return t;} SeekBar bar(int v){SeekBar s=new SeekBar(this);s.setMax(100);s.setProgress(v);return s;} Spinner spin(String[] a){Spinner s=new Spinner(this);s.setAdapter(new ArrayAdapter<String>(this,android.R.layout.simple_spinner_dropdown_item,a));return s;}
@Override public void onCreate(Bundle b){super.onCreate(b);l=new LinearLayout(this);l.setOrientation(LinearLayout.VERTICAL);l.setPadding(22,16,22,24);ScrollView sv=new ScrollView(this);sv.addView(l);setContentView(sv);l.addView(tv("LiveWebWallpaper 4.0"));l.addView(tv("Matrix / Code / Web — موتور زنده و روان"));l.addView(tv("حالت"));mode=spin(new String[]{"Web","Matrix","Code"});l.addView(mode);l.addView(tv("آدرس Web"));url=new EditText(this);url.setSingleLine();l.addView(url);l.addView(tv("سرعت Matrix"));sp=bar(Prefs.speed(this));l.addView(sp);l.addView(tv("سرعت تایپ Code"));cp=bar(Prefs.codeSpeed(this));l.addView(cp);l.addView(tv("کم‌رنگی"));dim=bar(Prefs.dim(this));l.addView(dim);l.addView(tv("Zoom وب (50 تا 200٪)"));zoom=bar((int)((Prefs.zoom(this)-.5f)/1.5f*100));l.addView(zoom);CheckBox hs=new CheckBox(this);hs.setText("عدم نمایش ScrollBar");hs.setChecked(Prefs.hideScroll(this));l.addView(hs);CheckBox fs=new CheckBox(this);fs.setText("تمام صفحه");fs.setChecked(Prefs.full(this));l.addView(fs);Button save=new Button(this);save.setText("ذخیره و انتخاب Live Wallpaper");l.addView(save);save.setOnClickListener(v->{String u=url.getText().toString().trim();if(u.length()==0)u="https://example.com";if(!u.startsWith("http://")&&!u.startsWith("https://"))u="https://"+u;Prefs.save(this,mode.getSelectedItemPosition(),Math.max(1,sp.getProgress()),Math.max(1,cp.getProgress()),bg,ac,dim.getProgress(),.5f+zoom.getProgress()/100f*1.5f,u,hs.isChecked(),fs.isChecked());Intent i=new Intent(WallpaperManager.ACTION_CHANGE_LIVE_WALLPAPER);i.putExtra(WallpaperManager.EXTRA_LIVE_WALLPAPER_COMPONENT,new ComponentName(this,LiveWallpaperService.class));startActivity(i);});Button sup=new Button(this);sup.setText("♥ حمایت از توسعه‌دهنده");l.addView(sup);sup.setOnClickListener(v->{new AlertDialog.Builder(this).setTitle("حمایت").setMessage("☕ https://coffeebede.com/shahabsystem\n\nhttps://reymit.ir/shahabsystem\n\n✉ hamedmohammadinikche@gmail.com\nGitHub: github.com/shahabsystem").setPositiveButton("بازگشت",null).show();});mode.setSelection(Prefs.mode(this));url.setText(Prefs.url(this));}
}
